targets.rawSql:
SELECT ROUND((COUNT(*) FILTER (
  WHERE GREATEST(ABS(pe_1),ABS(pe_2),ABS(pe_3),ABS(pe_4),ABS(pe_5),ABS(pe_6)) <= pe_setting
    AND GREATEST(ABS(je_1),ABS(je_2),ABS(je_3),ABS(je_4)) <= je_setting
)::NUMERIC / NULLIF(COUNT(*) FILTER (WHERE pe_1 IS NOT NULL), 0)) * 100, 1) AS value
FROM public.ldi_data
WHERE $__timeFilter(time) AND factory IN ($Factory) AND process IN ($process);

